fn point2(reader:&mut store::ByteReader<'_>)->Result<SemioPoint2,ValueError>{Ok(SemioPoint2{x:f64(reader)?,y:f64(reader)?})}
fn point3(reader:&mut store::ByteReader<'_>)->Result<SemioPoint3,ValueError>{Ok(SemioPoint3{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?})}
fn transform(reader:&mut store::ByteReader<'_>)->Result<SemioTransform,ValueError>{Ok(SemioTransform{translation:point3(reader)?,rotation:SemioQuaternion{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?,w:f64(reader)?},scale:point3(reader)?})}
fn rgba(reader:&mut store::ByteReader<'_>)->Result<SemioRgba,ValueError>{Ok(SemioRgba{r:f32(reader)?,g:f32(reader)?,b:f32(reader)?,a:f32(reader)?})}
fn boolean(value:u8)->Result<bool,ValueError>{match value{0=>Ok(false),1=>Ok(true),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native boolean"))}}
fn option<T>(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,read:impl FnOnce(&mut store::ByteReader<'_>,&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<Option<T>,ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>Ok(None),1=>read(reader,control).map(Some),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native optional presence"))}}
