fn point3_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioPoint3,ValueError>{let[x,y,z]=native::record(value,control)?;Ok(SemioPoint3{x:native::float(x,control)?,y:native::float(y,control)?,z:native::float(z,control)?})}
